// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {TimelockController} from "../src/TimelockController.sol";

contract InvMutTest is Test {
    TimelockController c;

    function setUp() public {
        c = new TimelockController(0, new address[](0), new address[](0));
    }

    function testFuzz_property(bytes32 role, address account) public {
        vm.assume(getRoleAdminReturn(role) != bytes32(0));
        vm.assume(account != address(this));
        vm.assume(account != address(0));

        assertFalse(c.hasRole(role, account));
    }

    function getRoleAdminReturn(bytes32 role) internal view returns (bytes32) {
        return c.getRoleAdmin(role);
    }
}
